/**
 * NET Study PDF.js worker bootstrap (PDF.js 3.11.174)
 * Tries multiple matching worker sources. The main library and worker version
 * are intentionally kept identical.
 */
(function(){
  'use strict';
  var urls=[
    'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js',
    'https://unpkg.com/pdfjs-dist@3.11.174/build/pdf.worker.min.js',
    'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'
  ],lastErr=null;
  for(var i=0;i<urls.length;i++){
    try{importScripts(urls[i]);return}catch(e){lastErr=e}
  }
  throw lastErr||new Error('PDF.js worker could not be loaded from any fallback source.');
})();
